def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    recent_len = 10 if n >= 10 else n
    opp_c = 0
    rec_c = 0
    start_recent = n - recent_len

    for i in range(n):
        o = history[i][1]
        if o == 'C':
            opp_c += 1
            if i >= start_recent:
                rec_c += 1

    opp_d = n - opp_c
    last_me, last_opp = history[-1]

    opp_c_streak = 0
    for m, o in reversed(history):
        if o == 'C':
            opp_c_streak += 1
        else:
            break

    opp_d_streak = 0
    for m, o in reversed(history):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    cc_streak = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'C':
            cc_streak += 1
        else:
            break

    cd_streak = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'D':
            cd_streak += 1
        else:
            break

    if n < 5:
        if opp_c == 0:
            if n >= 2:
                return 'D'
            return 'C'
        if opp_d_streak >= 2:
            return 'D'
        if opp_d >= 2 and opp_d > opp_c:
            return 'D'
        return 'C'

    C_after_C = 0
    D_after_C = 0
    C_after_D = 0
    D_after_D = 0
    ctx_c = 0
    ctx_d = 0
    ctx_key = (last_me, last_opp)

    for i in range(1, n):
        prev_me = history[i - 1][0]
        cur_opp = history[i][1]

        if prev_me == 'C':
            if cur_opp == 'C':
                C_after_C += 1
            else:
                D_after_C += 1
        else:
            if cur_opp == 'C':
                C_after_D += 1
            else:
                D_after_D += 1

        if history[i - 1] == ctx_key:
            if cur_opp == 'C':
                ctx_c += 1
            else:
                ctx_d += 1

    if opp_c == 0:
        return 'D'

    if opp_d == 0:
        if C_after_D > 0:
            return 'D'
        if last_me == 'D' and last_opp == 'C':
            return 'C'
        return 'D'

    if recent_len >= 6 and rec_c == 0:
        return 'D'

    if opp_d * 10 >= n * 7:
        return 'D'

    if last_me == 'D' and last_opp == 'C' and C_after_D + D_after_D == 0:
        return 'C'

    if cd_streak >= 2:
        return 'D'

    p_overall = (opp_c + 1.0) / (n + 2.0)
    p_recent = (rec_c + 1.0) / (recent_len + 2.0)

    ctx_total = ctx_c + ctx_d
    if ctx_total >= 3:
        p_ctx = (ctx_c + 1.0) / (ctx_total + 2.0)
    else:
        p_ctx = p_overall

    p_cur = 0.35 * p_ctx + 0.35 * p_recent + 0.30 * p_overall

    p_if_C = (C_after_C + 1.0) / (C_after_C + D_after_C + 2.0)
    p_if_D = (C_after_D + 1.0) / (C_after_D + D_after_D + 2.0)

    if last_opp == 'C' and opp_c * 4 >= n * 3 and opp_c_streak >= 8:
        d_resp = C_after_D + D_after_D
        if d_resp == 0:
            if rng.random() < 0.07:
                return 'D'
        elif D_after_D == 0 and C_after_D >= 1:
            if rng.random() < 0.45:
                return 'D'
        elif C_after_D >= 2 and C_after_D > D_after_D:
            if rng.random() < 0.25:
                return 'D'

    rem = 100 - n
    if rem > 60:
        F = 14.0
    elif rem > 30:
        F = 10.0
    elif rem > 15:
        F = 6.0
    else:
        F = 3.0

    score_C = 3.0 * p_cur + F * p_if_C
    score_D = 1.0 + 4.0 * p_cur + F * p_if_D

    if last_opp == 'D':
        if opp_c * 2 >= n:
            score_C += 0.8
            if opp_d_streak <= 1:
                score_C += 0.5
        if opp_d_streak >= 3 and opp_c * 3 < n:
            score_D += 1.5
        if cd_streak == 1 and opp_c * 4 >= n * 3:
            score_C += 0.3
    else:
        if opp_c * 4 >= n * 3 and opp_c_streak >= 8:
            score_D += 0.7
        if p_if_D >= 0.55 and opp_d <= 2:
            score_D += 0.8
        if rec_c >= recent_len - 1:
            score_D += 0.5
        if cc_streak >= 8 and opp_d <= 2:
            score_D += 0.4

    if score_D > score_C:
        return 'D'
    return 'C'
